import random
import threading
import time
from collections import defaultdict
from dataclasses import dataclass, field
from enum import Enum
from typing import Dict, List, Optional, Tuple, Set


class Ability(Enum):
    STRENGTH = "strength"
    AGILITY = "agility"
    INTELLIGENCE = "intelligence"
    STEALTH = "stealth"


class EnvironmentType(Enum):
    FOREST = "forest"
    CAVE = "cave"
    RUINS = "ruins"


@dataclass
class Player:
    id: int
    name: str
    ability: Ability
    team: str
    position: Tuple[int, int] = (0, 0)
    treasures_collected: int = 0
    alive: bool = True
    active_puzzle: Optional[str] = None

    def move(self, dx: int, dy: int) -> bool:
        if not self.alive:
            return False
        self.position = (self.position[0] + dx, self.position[1] + dy)
        return True

    def use_ability(self, puzzle_type: str) -> bool:
        """Check if player's ability is suitable for the puzzle type."""
        mapping = {
            "heavy_object": Ability.STRENGTH,
            "tight_space": Ability.AGILITY,
            "riddle": Ability.INTELLIGENCE,
            "trap_avoidance": Ability.STEALTH,
        }
        required = mapping.get(puzzle_type)
        return required == self.ability if required else False


@dataclass
class Puzzle:
    id: str
    type: str  # maps to Ability mapping above
    required_solvers: int = 1
    solved: bool = False
    difficulty: int = 1  # 1-5 scale
    reward: int = 1  # treasure units

    def attempt_solve(self, solvers: List[Player]) -> Tuple[bool, str]:
        if self.solved:
            return False, "Already solved"
        if len(solvers) < self.required_solvers:
            return False, f"Need at least {self.required_solvers} solvers"

        # Check if at least one solver has the required ability
        has_required = any(p.use_ability(self.type) for p in solvers)
        if not has_required:
            return False, f"No solver has required ability for {self.type}"

        # Success probability based on difficulty and number of solvers
        base_success = 0.7
        difficulty_penalty = (self.difficulty - 1) * 0.1
        success_prob = max(0.1, base_success - difficulty_penalty + len(solvers) * 0.05)

        success = random.random() < success_prob
        if success:
            self.solved = True
            return True, "Puzzle solved!"
        else:
            return False, "Puzzle attempt failed. Try again."


